int x = 10;
int* p = &x;
int** pp = &p;
int*** ppp = &pp;

// Dereferencing path: ppp -> pp -> p -> x
int value = ***ppp;

// --- Arrays of Pointers (Higher Precedence: [])
int a=1, b=2;
int *ptr_array[2]; // array of 2 pointers to int
ptr_array[0] = &a;
ptr_array[1] = &b;
int val_a = *ptr_array[0]; // 1

// --- Pointers to Arrays (Parentheses required)
int arr[5] = {10, 20, 30, 40, 50};
int (*ptr_to_array)[5]; // pointer to an array of 5 ints
ptr_to_array = &arr;

// Accessing elements:
int val_b = (*ptr_to_array)[2]; // 30

// --- 2D Array and Pointer Equivalence
int matrix[2][3] = {{1, 2, 3}, {4, 5, 6}};

// matrix is type 'pointer to array of 3 ints'
// int (*)[3]
int (*row_ptr)[3] = matrix;

// Accessing elements via pointer arithmetic
int v1 = matrix[1][2]; // 6
int v2 = *(*(matrix + 1) + 2); // 6 (Equivalent to v1)
